  <script type="module">
    function clampPercent(value) {
      const numeric = Number(value);
      if (Number.isNaN(numeric)) {
        return 0;
      }
      return Math.max(0, Math.min(100, numeric));
    }

    function stageText(stage) {
      const map = {
        "蟄伏": "遠處守望，仍在壓低存在感",
        "試爪": "開始靠近，試探你的邊界",
        "圈地": "佔有慾升溫，安全感還不穩",
        "築巢": "想把你圍進自己的世界",
        "安家": "安全感落地，開始談未來"
      };
      return _.get(map, stage, "等待變量初始化");
    }

    function renderMeter(selector, value) {
      const safe = clampPercent(value);
      $(`${selector} .sr-value`).text(String(safe));
      $(`${selector} .sr-fill`).css("width", `${safe}%`);
    }

    function populateCharacterData() {
      const all_variables = getAllVariables();
      const possess = _.get(all_variables, "stat_data.石睿.佔有慾", 1);
      const safety = _.get(all_variables, "stat_data.石睿.安全感", 1);
      const intimacy = _.get(all_variables, "stat_data.石睿.親密度", 1);
      const stage = _.get(all_variables, "stat_data.石睿._階段", "蟄伏");
      const live = _.get(all_variables, "stat_data.石睿.直播中", false);

      $("#sr-stage").text(stage);
      $("#sr-stage-line").text(stageText(stage));
      $("#sr-live").attr("data-live", String(live));
      $("#sr-live .sr-live-text").text(live ? "裏帳直播中" : "待命");

      renderMeter("#sr-possess", possess);
      renderMeter("#sr-safety", safety);
      renderMeter("#sr-intimacy", intimacy);
    }

    async function init() {
      await waitGlobalInitialized("Mvu");
      populateCharacterData();
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });
    }

    $(errorCatched(init));
  </script>
