    if (doc.visibilityState === 'hidden' && settings.ignoreVisibility !== true) return null;
    if (doc.getElementById(MODAL_ID) && settings.allowOverModal !== true) return null;
    if (settings.bypassCooldown !== true && nowMs - (Number(petState.lastWhisperAt) || 0) < Number(config.cooldowns.proactiveMs || 900000)) return null;
    syncHiddenLetters();
    var entry = chooseContextWhisper(settings);
    if (!entry) return null;
    if (entry.kind === 'night-knock') {
      var knockEnabled = typeof petState.knockEnabled === 'boolean' ? petState.knockEnabled : config.defaults.knockEnabled !== false;
      if (!knockEnabled) return null;
      if (nowMs - (Number(petState.lastKnockAt) || 0) < Number(config.cooldowns.knockMs || 2700000)) return null;
    }
    return showWhisper(entry, { nowMs: nowMs, visibleMs: settings.visibleMs });
  }

  async function generateDeskLine() {
    var petState = readPetState();
    var mode = letterMode(petState);
    if (mode === 'local') throw new Error('「叫他說一句」需要模型。請先在相處設定選酒館主連線或指定副連線。');
    var manual = dialogueConfig().manualLine || {};
    var state = readState(), stat = state.stat || {};
    var prompt = [
      manual.prompt || '請以石睿口吻只說一句繁體中文。',
      '狀態：階段 ' + phaseName(state) + '，安全感 ' + numberLabel(stat['安全感']) + '，佔有慾 ' + numberLabel(stat['佔有慾']) + '，親密度 ' + numberLabel(stat['親密度']) + '，直播中 ' + String(stat['直播中'] === true ? '是' : '否') + '。',
      recentConversation(6) ? '最近對話：\n' + recentConversation(6) : ''
    ].filter(Boolean).join('\n\n');
    var result, source;
    if (mode === 'profile') {
      var profiles = getConnectionProfiles();
      var profile = profiles.find(function(item) { return item.id === String(petState.letterProfileId || ''); });
      if (!profile) throw new Error('找不到指定的連線設定檔。請回到相處設定重新選擇副連線。');
      var slash = findApi('triggerSlash');
      if (!slash) throw new Error('酒館指令沒有接上，無法使用指定副連線。');
      var command = '/profile-genstream profile=' + slashQuote(profile.id) + ' reasoning=false length=' + Number(manual.responseLength || 180) + ' generating=' + slashQuote('石睿抬眼看過來……') + ' completed=' + slashQuote('他把話留在桌邊') + ' delay=500 stop=true ' + slashQuote(prompt);
      result = await slash(command);
      source = '指定副連線 · ' + profile.name + (profile.model ? ' · ' + profile.model : '');
    } else {
      var generate = findApi('generate');
      if (generate) result = await generate({ user_input: prompt, should_stream: false, should_silence: true, max_chat_history: 10 });
      else {
        var quiet = findApi('generateQuietPrompt');
        if (!quiet) throw new Error('找不到酒館生成介面；請確認 TavernHelper 已啟用。');
        result = await quiet({ quietPrompt: prompt, responseLength: Number(manual.responseLength || 180), removeReasoning: true, trimToSentence: true });
      }
      source = '沿用目前酒館連線';
    }
    var text = cleanGeneratedLetter(result).replace(/\s+/g, ' ').replace(/^[「『“"]+|[」』”"]+$/g, '').trim();
    text = clipText(text, Number(manual.maxChars) || 80);
    var at = new Date().toISOString();
    savePetState({ lastGeneratedDeskLine: text, lastGeneratedDeskLineSource: source, lastGeneratedDeskLineAt: at, lastInteractionAt: Date.now(), deskLineError: '' });
    showWhisper({ id: 'manual-' + at, kind: 'manual-line', text: text, mood: letterMood(text, 'tease'), action: 'home' }, { visibleMs: 14000 });
    return { text: text, source: source, generated: true };
  }

  function stopWhisperScheduler() {
    host.clearInterval(dialogueRuntime.interval);
    host.clearTimeout(dialogueRuntime.initial);
    host.clearTimeout(dialogueRuntime.hide);
    dialogueRuntime.interval = 0;
    dialogueRuntime.initial = 0;
    dialogueRuntime.hide = 0;
  }

  function startWhisperScheduler() {
    stopWhisperScheduler();
    syncHiddenLetters();
    var config = dialogueConfig();
    dialogueRuntime.initial = host.setTimeout(function() { evaluateWhisper({ reason: 'initial' }); }, Number(config.cooldowns.initialDelayMs) || 35000);
    dialogueRuntime.interval = host.setInterval(function() { evaluateWhisper({ reason: 'timer' }); }, Number(config.cooldowns.schedulerMs) || 60000);
  }

