  function reducedMotion() {
    try { return Boolean(host.matchMedia && host.matchMedia('(prefers-reduced-motion: reduce)').matches); }
    catch (e) { return false; }
  }

  function requestFrame(callback) {
    if (typeof host.requestAnimationFrame === 'function') return host.requestAnimationFrame(callback);
    return host.setTimeout(function() { callback(Date.now()); }, 33);
  }

  function cancelFrame(handle) {
    if (!handle) return;
    if (typeof host.cancelAnimationFrame === 'function') host.cancelAnimationFrame(handle);
    else host.clearTimeout(handle);
  }

  function spriteSequence(name) {
    return SPRITE_ATLAS.sequences[name] || SPRITE_ATLAS.sequences.idle;
  }

  function renderSpriteFrame() {
    var root = doc.getElementById(ROOT_ID);
    if (!root) return;
    var sprite = root.querySelector('.srr-pet-sprite');
    if (!sprite) return;
    var sequence = spriteSequence(spriteAnimation.name);
    var frame = sequence.frames[Math.min(spriteAnimation.frame, sequence.frames.length - 1)] || 0;
    var x = SPRITE_ATLAS.columns > 1 ? frame * 100 / (SPRITE_ATLAS.columns - 1) : 0;
    var y = SPRITE_ATLAS.rows > 1 ? sequence.row * 100 / (SPRITE_ATLAS.rows - 1) : 0;
    sprite.style.backgroundPosition = x + '% ' + y + '%';
    root.setAttribute('data-sprite-sequence', spriteAnimation.name);
    root.setAttribute('data-sprite-frame', String(frame));
  }

  function spriteTick(timestamp) {
    spriteAnimation.raf = 0;
    if (!alive() || reducedMotion()) return;
    var sequence = spriteSequence(spriteAnimation.name);
    var interval = 1000 / Math.max(1, sequence.fps || 4);
    if (!spriteAnimation.lastAt) spriteAnimation.lastAt = timestamp;
    if (timestamp - spriteAnimation.lastAt >= interval) {
      spriteAnimation.lastAt = timestamp;
      spriteAnimation.frame += 1;
      if (spriteAnimation.frame >= sequence.frames.length) {
        if (sequence.loop && !spriteAnimation.once) spriteAnimation.frame = 0;
        else {
          setSpriteSequence(spriteAnimation.returnTo || moodFor(readState()));
          return;
        }
      }
      renderSpriteFrame();
    }
    spriteAnimation.raf = requestFrame(spriteTick);
  }

  function setSpriteSequence(name, options) {
    var sequenceName = SPRITE_ATLAS.sequences[name] ? name : 'idle';
    var settings = options || {};
    cancelFrame(spriteAnimation.raf);
    spriteAnimation.name = sequenceName;
    spriteAnimation.frame = 0;
    spriteAnimation.lastAt = 0;
    spriteAnimation.once = settings.once === true;
    spriteAnimation.returnTo = settings.returnTo || moodFor(readState());
    renderSpriteFrame();
    if (!reducedMotion()) spriteAnimation.raf = requestFrame(spriteTick);
  }

  function setPortrait(mood, options) {
    var root = doc.getElementById(ROOT_ID);
    if (!root) return;
    var portrait = root.querySelector('.srr-pet-portrait');
    if (!portrait) return;
    if (!SPRITE_READY) {
      portrait.innerHTML = '<span class="srr-pet-fallback" aria-label="石睿桌寵圖片待安裝">睿</span>';
      root.setAttribute('data-sprite-sequence', SPRITE_ATLAS.sequences[mood] ? mood : 'idle');
      return;
    }
    var sprite = portrait.querySelector('.srr-pet-sprite');
    if (!sprite) {
      portrait.innerHTML = '';
      sprite = doc.createElement('span');
      sprite.className = 'srr-pet-sprite';
      sprite.setAttribute('aria-hidden', 'true');
      sprite.style.backgroundImage = 'url("' + SPRITE_SHEET_URL + '")';
      portrait.appendChild(sprite);
    }
    setSpriteSequence(mood, options);
  }

  function viewportBox() {
    var viewport = host.visualViewport;
    var left = viewport && Number.isFinite(viewport.offsetLeft) ? viewport.offsetLeft : 0;
    var top = viewport && Number.isFinite(viewport.offsetTop) ? viewport.offsetTop : 0;
    var width = viewport && Number.isFinite(viewport.width) ? viewport.width : (host.innerWidth || doc.documentElement.clientWidth || 0);
    var height = viewport && Number.isFinite(viewport.height) ? viewport.height : (host.innerHeight || doc.documentElement.clientHeight || 0);
    return { left: left, top: top, right: left + width, bottom: top + height, width: width, height: height };
  }

  function mobileLayout() {
    return viewportBox().width <= 1000;
  }

  function clampPetSizePercent(value) {
    var numeric = Number(value);
    if (!Number.isFinite(numeric)) numeric = 100;
    return Math.max(60, Math.min(180, Math.round(numeric / 10) * 10));
  }

  function petSizePercent(state) {
    var petState = state || readPetState();
    return clampPetSizePercent(mobileLayout() ? petState.sizeMobile : petState.sizeDesktop);
  }

  function applyPetSize(value, persist) {
    var percent = clampPetSizePercent(value);
    var root = doc.getElementById(ROOT_ID);
    if (root) {
      var baseSize = mobileLayout() ? 104 : 128;
      root.style.setProperty('--srr-pet-size', (baseSize * percent / 100) + 'px');
      root.setAttribute('data-pet-size-percent', String(percent));
    }
    if (persist === true) {
      var patch = {};
      patch[mobileLayout() ? 'sizeMobile' : 'sizeDesktop'] = percent;
      savePetState(patch);
    }
    return percent;
  }

  function petBounds(root) {
    var viewport = viewportBox();
    var margin = viewport.width <= 1000 ? 10 : 18;
    var safeBottom = viewport.bottom - margin;
    var composer = doc.getElementById('form_sheld');
    if (composer) {
      var rect = composer.getBoundingClientRect();
      if (rect.height > 0 && rect.top > viewport.top && rect.top < viewport.bottom) safeBottom = Math.min(safeBottom, rect.top - margin);
    }
    var width = root.offsetWidth || (viewport.width <= 1000 ? 104 : 128);
    var height = root.offsetHeight || (viewport.width <= 1000 ? 104 : 128);
    var minX = viewport.left + margin;
    var minY = viewport.top + margin;
    return {
      minX: minX,
      minY: minY,
      maxX: Math.max(minX, viewport.right - width - margin),
      maxY: Math.max(minY, safeBottom - height)
    };
  }

  function clampPet(root, x, y) {
    var bounds = petBounds(root);
    return {
      x: Math.max(bounds.minX, Math.min(bounds.maxX, Number.isFinite(x) ? x : bounds.maxX)),
      y: Math.max(bounds.minY, Math.min(bounds.maxY, Number.isFinite(y) ? y : bounds.maxY))
    };
  }

  function syncPetLayout() {
    layoutState.frame = 0;
    var root = doc.getElementById(ROOT_ID);
    if (!root) return;
    applyPetSize(petSizePercent(readPetState()), false);
    var rect = root.getBoundingClientRect();
    var state = readPetState();
    var desiredX = Number.isFinite(state.x) ? state.x : rect.left;
    var desiredY = Number.isFinite(state.y) ? state.y : rect.top;
    var point = clampPet(root, desiredX, desiredY);
    root.style.left = Math.round(point.x) + 'px';
    root.style.top = Math.round(point.y) + 'px';
    root.style.right = 'auto';
  }

  function schedulePetLayout() {
    if (layoutState.frame) return;
    layoutState.frame = requestFrame(syncPetLayout);
  }

  function clearPetLayout() {
    cancelFrame(layoutState.frame);
    layoutState.frame = 0;
    if (layoutState.observer) layoutState.observer.disconnect();
    if (layoutState.mutationObserver) layoutState.mutationObserver.disconnect();
    layoutState.observer = null;
    layoutState.mutationObserver = null;
    layoutState.disposers.splice(0).forEach(function(dispose) { try { dispose(); } catch (e) {} });
  }

  function watchPetLayout() {
    clearPetLayout();
    function listen(target, eventName) {
      if (!target || typeof target.addEventListener !== 'function') return;
      target.addEventListener(eventName, schedulePetLayout, { passive: true });
      layoutState.disposers.push(function() { target.removeEventListener(eventName, schedulePetLayout); });
    }
    listen(host, 'resize');
    listen(host, 'orientationchange');
    listen(host.visualViewport, 'resize');
    listen(host.visualViewport, 'scroll');
    if (typeof host.ResizeObserver === 'function') {
      layoutState.observer = new host.ResizeObserver(schedulePetLayout);
      var composer = doc.getElementById('form_sheld');
      if (composer) layoutState.observer.observe(composer);
    }
    if (typeof host.MutationObserver === 'function') {
      layoutState.mutationObserver = new host.MutationObserver(function() {
        var composer = doc.getElementById('form_sheld');
        if (composer && layoutState.observer) layoutState.observer.observe(composer);
        schedulePetLayout();
      });
      layoutState.mutationObserver.observe(doc.body, { childList: true, subtree: true });
    }
    schedulePetLayout();
  }

  function mountPet() {
    stopWhisperScheduler();
    var existing = doc.getElementById(ROOT_ID);
    if (existing) existing.remove();
    ensureStyle();
    var state = readPetState();
    var root = doc.createElement('div');
    root.id = ROOT_ID;
    root.setAttribute('data-shirui-pet', 'v2');
    root.setAttribute('data-sprite-atlas', '8x12');
    root.setAttribute('data-sprite-ready', SPRITE_READY ? 'true' : 'false');
    if (state.night === true) root.classList.add('srr-night');
    root.innerHTML = '<button class="srr-pet-whisper" type="button" data-whisper-action="home" aria-live="polite">妳忙妳的。我在。</button><button class="srr-pet-orb" type="button" aria-label="打開石睿桌寵"><span class="srr-pet-portrait"></span></button>';
    doc.body.appendChild(root);
    var initialWhisper = chooseContextWhisper({ nowMs: Date.now() });
    if (initialWhisper) {
      var initialBubble = root.querySelector('.srr-pet-whisper');
      initialBubble.textContent = initialWhisper.text;
      initialBubble.setAttribute('data-whisper-action', initialWhisper.action || 'home');
      initialBubble.setAttribute('data-whisper-kind', initialWhisper.kind || 'context');
    }
    applyPetSize(petSizePercent(state), false);
    setPortrait(moodFor(readState()));
    var initial = clampPet(root, state.x, state.y);
    root.style.left = Math.round(initial.x) + 'px';
    root.style.top = Math.round(initial.y) + 'px';
    root.style.right = 'auto';
    watchPetLayout();
    startWhisperScheduler();

    var button = root.querySelector('.srr-pet-orb');
    var whisper = root.querySelector('.srr-pet-whisper');
    whisper.addEventListener('click', function(event) {
      event.preventDefault();
      event.stopPropagation();
      touchDeskActivity();
      var action = whisper.getAttribute('data-whisper-action') || 'home';
      whisper.classList.remove('srr-visible');
      if (action.indexOf('hidden:') === 0) openHiddenLetter(action.slice(7));
      else openPet(action);
    });
    var drag = null;
    button.addEventListener('pointerdown', function(event) {
      touchDeskActivity();
      drag = { id: event.pointerId, sx: event.clientX, sy: event.clientY, x: root.getBoundingClientRect().left, y: root.getBoundingClientRect().top, moved: false, sequence: '' };
      setPortrait('tap', { once: true, returnTo: moodFor(readState()) });
      try { button.setPointerCapture(event.pointerId); } catch (e) {}
    });
    button.addEventListener('pointermove', function(event) {
      if (!drag || drag.id !== event.pointerId) return;
      var dx = event.clientX - drag.sx, dy = event.clientY - drag.sy;
      if (Math.abs(dx) + Math.abs(dy) > 5) drag.moved = true;
      if (!drag.moved) return;
      var walking = dx < 0 ? 'walkLeft' : 'walkRight';
      if (drag.sequence !== walking) { drag.sequence = walking; setPortrait(walking); }
      var point = clampPet(root, drag.x + dx, drag.y + dy);
      root.style.left = point.x + 'px'; root.style.top = point.y + 'px'; root.style.right = 'auto';
    });
    function finishDrag(event, cancelled) {
      if (!drag || drag.id !== event.pointerId) return;
      var moved = drag.moved; drag = null;
      if (cancelled) { setPortrait(moodFor(readState())); return; }
      if (moved) {
        var rect = root.getBoundingClientRect();
        savePetState({ x: Math.round(rect.left), y: Math.round(rect.top) });
        setPortrait('turn', { once: true, returnTo: moodFor(readState()) });
      } else {
        setPortrait('tease', { once: true, returnTo: moodFor(readState()) });
        openPet('home');
      }
    }
    button.addEventListener('pointerup', function(event) { finishDrag(event, false); });
    button.addEventListener('pointercancel', function(event) { finishDrag(event, true); });
  }

  function modalShell(title, subtitle) {
    touchDeskActivity();
    var old = doc.getElementById(MODAL_ID);
    if (old) old.remove();
    var overlay = doc.createElement('div');
    overlay.id = MODAL_ID;
    overlay.innerHTML = '<section class="srr-modal" role="dialog" aria-modal="true" aria-labelledby="srr-modal-title"><header class="srr-head"><div><p class="srr-eyebrow">POLICE FILE · DESK WATCH</p><h2 class="srr-title" id="srr-modal-title">' + escapeHtml(title) + '</h2><p class="srr-sub">' + escapeHtml(subtitle || '') + '</p></div><button class="srr-close" type="button" aria-label="關閉">✕</button></header><div class="srr-body"></div></section>';
    var closeButton = overlay.querySelector('.srr-close');
    closeButton.addEventListener('click', closePet);
    overlay.addEventListener('pointerdown', function(event) { if (event.target === overlay) closePet(); });
    overlay.addEventListener('keydown', function(event) {
      if (event.key === 'Escape') { event.preventDefault(); closePet(); }
    });
    doc.body.appendChild(overlay);
    try { closeButton.focus(); } catch (e) {}
    return overlay.querySelector('.srr-body');
  }

  function closePet() {
    var modal = doc.getElementById(MODAL_ID);
    if (modal) modal.remove();
    setPortrait(moodFor(readState()));
    try {
