    var unread = (Array.isArray(petState.unreadHiddenLetterIds) ? petState.unreadHiddenLetterIds : []).filter(function(item) { return item !== id; });
    var readAt = new Date().toISOString();
    savePetState({ unreadHiddenLetterIds: unread, letterReadAt: readAt, lastReadLetterId: id, lastReadLetterText: letter.text });
    setPortrait(letter.mood || letterMood(letter.text, 'fond'));
