    body.querySelector('#srr-pet-size-reset').addEventListener('click', function() { updateSize(100); });
    body.querySelector('#srr-pet-size-plus').addEventListener('click', function() { updateSize(Number(sizeRange.value) + 10); });
    body.querySelector('#srr-letter-mode').addEventListener('change', function(event) {
      var nextMode = event.currentTarget.value;
      savePetState({ letterMode: nextMode });
      var field = body.querySelector('#srr-letter-profile-field');
      field.hidden = nextMode !== 'profile';
    });
    body.querySelector('#srr-letter-profile').addEventListener('change', function(event) {
      savePetState({ letterProfileId: event.currentTarget.value });
    });
    body.querySelector('#srr-bubbles').addEventListener('click', function() { savePetState({ bubbleEnabled: !bubbleEnabled }); mountPet(); openSettings(); });
    body.querySelector('#srr-knock').addEventListener('click', function() { savePetState({ knockEnabled: !knockEnabled }); mountPet(); openSettings(); });
    body.querySelector('#srr-night').addEventListener('click', function() { savePetState({ night: state.night !== true }); mountPet(); openSettings(); });
    body.querySelector('#srr-reset-position').addEventListener('click', function() { savePetState({ x: null, y: null }); mountPet(); notify('石睿已回到右下角。', 'success'); });
  }

  function openDiagnostics() {
    var checks = [
      ['TavernHelper 按鈕事件', !!findApi('getButtonEvent') && !!findApi('eventOn')],
      ['MVU', !!findValue('Mvu')],
      ['聊天變量', !!findApi('getVariables') && !!findApi('insertOrAssignVariables')],
      ['酒館指令', !!findApi('triggerSlash')],
      ['書信副連線', getConnectionProfiles().length > 0],
      ['桌邊對話設定', dialogueConfig().schemaVersion !== 'fallback']
    ];
    var body = modalShell('哪裡斷線了', '紅燈不裝死；依照缺失項目重新啟用對應腳本或擴充。');
    body.innerHTML = '<div class="srr-vitals">' + checks.map(function(item) { return '<div class="srr-vital"><span>' + item[0] + '</span><strong style="color:' + (item[1] ? '#8eb49e' : '#d98270') + '">' + (item[1] ? '已連線' : '未連線') + '</strong></div>'; }).join('') + '</div><div class="srr-rule">若 MVU 未連線，確認 MVU 與 TavernHelper 已安裝並啟用。若副連線未讀到，先到 ST Connection Manager 建立 Connection Profile；卡片不保存網址或金鑰。</div><div class="srr-actions"><button class="srr-btn" data-page="diagnostics">重新偵測</button><button class="srr-btn" data-page="home">返回</button></div>';
    bindActions(body);
  }

  function showError(message) {
    var body = modalShell('連線沒有接好', message || '未知錯誤');
    body.innerHTML = '<div class="srr-error">' + escapeHtml(message || '未知錯誤') + '</div><div class="srr-actions"><button class="srr-btn" data-page="diagnostics">打開診斷</button><button class="srr-btn" data-page="home">返回</button></div>';
    bindActions(body);
  }

  function openPet(page) {
    if (!alive()) return false;
    if (page === 'status') openStatus();
    else if (page === 'letters') openLetters();
    else if (page === 'settings') openSettings();
    else if (page === 'diagnostics') openDiagnostics();
    else openHome();
    return true;
  }

  function registerSlashEntry() {
    try {
      var Parser = findValue('SlashCommandParser');
      var Command = findValue('SlashCommand');
      if (Parser && typeof Parser.addCommandObject === 'function' && Command && typeof Command.fromProps === 'function') {
        Parser.addCommandObject(Command.fromProps({
          name: 'shirui', aliases: ['sr-pet'],
          callback: function() { openPet('home'); return ''; },
          returns: 'empty string; opens Shirui HTML without sending a message',
          helpString: '<div>開啟石睿桌寵與信件介面，不送出聊天訊息。</div>'
        }));
        return true;
      }
    } catch (e) { console.info('[石睿桌寵] modern slash registration skipped', e); }
    try {
      var legacy = findApi('registerSlashCommand');
      if (legacy) {
        legacy('shirui', function() { openPet('home'); return ''; }, ['sr-pet'], '開啟石睿桌寵與信件 HTML，不送出訊息', true, true);
        return true;
      }
    } catch (e2) { console.info('[石睿桌寵] legacy slash registration skipped', e2); }
    return false;
  }

  async function setupQR(canRunCommand) {
    if (!canRunCommand) return;
    var slash = findApi('triggerSlash');
    if (!slash) return;
    try {
      var raw = await slash('/qr-set-list');
      var sets = [];
      try { sets = JSON.parse(raw || '[]'); } catch (e) {}
      if (!Array.isArray(sets)) sets = [];
            if (sets.indexOf(QR_SET) < 0) {
        await slash('/qr-set-create nosend=true ' + QR_SET);
        await slash('/qr-create set="' + QR_SET + '" label="💌 石睿" title="開啟石睿的桌寵與信件介面，不送訊息" /shirui');
      }
      await slash('/qr-chat-set-on visible=true ' + QR_SET);
    } catch (e2) {
      console.info('[石睿桌寵] QR 自動建立失敗；TavernHelper 按鈕仍可使用', e2);
    }
  }

  function bindToolbar() {
    try {
      var on = findApi('eventOn'), getEvent = findApi('getButtonEvent');
      if (!on || !getEvent) throw new Error('button_api_unavailable');
      on(getEvent(BUTTON), function() { openPet('home'); });
    } catch (e) { notify('工具列按鈕沒有接上；桌面上的石睿仍可直接點。', 'warning'); }
  }

  var previous = globalThis[KEY];
  if (previous && typeof previous.destroy === 'function') {
    try { previous.destroy(); } catch (e) {}
  }
  var petApi = {
    token: token,
    assets: { spriteSheet: SPRITE_SHEET_URL, atlas: SPRITE_ATLAS },
    openPet: openPet,
    getConnectionProfiles: getConnectionProfiles,
    generateLetter: generateLetter,
    generateDeskLine: generateDeskLine,
    chooseContextWhisper: chooseContextWhisper,
    evaluateWhisper: evaluateWhisper,
    showWhisper: showWhisper,
    getUnlockedLetters: function() { return syncHiddenLetters().available.slice(); },
    openHiddenLetter: openHiddenLetter,
    setSizePercent: function(value) { var next = applyPetSize(value, true); schedulePetLayout(); return next; },
    setSpriteSequence: setSpriteSequence,
    close: closePet,
    destroy: function() {
      stopWhisperScheduler();
      clearPetLayout();
      cancelFrame(spriteAnimation.raf);
      spriteAnimation.raf = 0;
      var root = doc.getElementById(ROOT_ID), modal = doc.getElementById(MODAL_ID);
      if (root) root.remove(); if (modal) modal.remove();
    }
  };
  globalThis[KEY] = petApi;
  var publishGlobal = findApi('initializeGlobal');
  if (publishGlobal) publishGlobal(PET_GLOBAL, petApi);
  else {
    try { host[PET_GLOBAL] = petApi; } catch (e) {}
  }

  mountPet();
  bindToolbar();
  setupQR(registerSlashEntry());
  console.info('[石睿桌寵] v2.7 ready; dialogue=' + dialogueConfig().schemaVersion + '; auto-generation=false; letter-profiles=' + getConnectionProfiles().length + '; user-size=60..180; mobile-safe-area=true; sprite=8x12/' + (SPRITE_READY ? 'ready' : 'placeholder') + '; qr=' + QR_SET);
});
